 if(path==='studio/project-settings'){manage();const target=db.projects.find(x=>x.id===p);for(const k of ['name','description'])if(k in body)target[k]=body[k];for(const k of ['guidelines','locked','archived','redundancy','independent'])if(k in body)db.prefs[p][k]=body[k];event('project_settings_updated');save();return {preferences:db.prefs[p]};}
